def glob_match(text, pattern):
    def match(ti, pi):
        if pi == len(pattern):
            return ti == len(text)
        if pattern[pi] == '*':
            while pi + 1 < len(pattern) and pattern[pi + 1] == '*':
                pi += 1
            if pi + 1 == len(pattern):
                return True
            for k in range(ti, len(text) + 1):
                if match(k, pi + 1):
                    return True
            return False
        if ti == len(text):
            return False
        if pattern[pi] == '?' or pattern[pi] == text[ti]:
            return match(ti + 1, pi + 1)
        return False
    return match(0, 0)

def rotate_ragged(rows, fill=None):
    def pad_rows(rows, fill):
        max_len = 0
        for row in rows:
            if len(row) > max_len:
                max_len = len(row)
        padded = []
        for row in rows:
            new_row = list(row)
            while len(new_row) < max_len:
                new_row.append(fill)
            padded.append(new_row)
        return padded

    def rotate_clockwise(matrix):
        if not matrix:
            return []
        height = len(matrix)
        width = len(matrix[0])
        rotated = []
        for col in range(width):
            new_row = []
            for row in range(height - 1, -1, -1):
                new_row.append(matrix[row][col])
            rotated.append(new_row)
        return rotated

    if not rows:
        return []
    padded = pad_rows(rows, fill)
    if not padded or not padded[0]:
        return []
    return rotate_clockwise(padded)

