def longest_unique(text):
    last = {}
    start = 0
    best = 0
    for i, ch in enumerate(text):
        if ch in last and last[ch] >= start:
            start = last[ch] + 1
        last[ch] = i
        length = i - start + 1
        if length > best:
            best = length
    return best

def lru_simulate(capacity, operations):
    def find_key(keys, key):
        for i in range(len(keys)):
            if keys[i] == key:
                return i
        return -1

    def remove_at(items, index):
        return items[:index] + items[index + 1:]

    def append_item(items, item):
        return items + [item]

    def get_value(entries, key):
        for entry in entries:
            if entry[0] == key:
                return entry[1]
        return None

    def update_entry(entries, key, value):
        result = []
        for entry in entries:
            if entry[0] == key:
                result.append([key, value])
            else:
                result.append(entry)
        return result

    def remove_entry(entries, key):
        result = []
        for entry in entries:
            if entry[0] != key:
                result.append(entry)
        return result

    keys = []
    entries = []
    get_results = []

    for op in operations:
        if op[0] == 'get':
            key = op[1]
            value = get_value(entries, key)
            get_results.append(value)
            if value is not None:
                index = find_key(keys, key)
                keys = remove_at(keys, index)
                keys = append_item(keys, key)
        else:
            key = op[1]
            value = op[2]
            index = find_key(keys, key)
            if index != -1:
                keys = remove_at(keys, index)
                entries = remove_entry(entries, key)
            keys = append_item(keys, key)
            entries = append_item(entries, [key, value])
            if capacity == 0:
                keys = []
                entries = []
            elif len(keys) > capacity:
                oldest = keys[0]
                keys = remove_at(keys, 0)
                entries = remove_entry(entries, oldest)

    return [get_results, keys]

